import { Grid, tile, shell, carve, replace, B, face } from "../../../../../../minecraft-design/tools/src/build.mjs";

const g = new Grid([40, 14, 36]);
const [W, H, D] = g.size;

const P = {
  wall: "stone_bricks",
  wall_moss: "mossy_stone_bricks",
  trim: "chiseled_stone_bricks",
  roof: "dark_oak",
  chimney: "red_bricks",
  porch: "oak",
  path: "gravel",
  path_accent: "light_gray_concrete",
  fence: "stone_brick_fence",
};

// Main farmhouse: x: 0-18, z: 0-14, y: 0-10
function house() {
  const houseX = [0, 18], houseZ = [0, 14], houseY = [0, 10];
  shell(g, { x: houseX, z: houseZ, y: houseY }, P.wall);

  // Floor at y: 5 (first storey / second storey split)
  for (let x = houseX[0]; x < houseX[1]; x++) {
    for (let z = houseZ[0]; z < houseZ[1]; z++) {
      g.set([x, 5, z], P.trim);
    }
  }

  // Windows (trapdoors as shutters): both storeys, front (z=0) and sides
  const shutterZone = [[2, 6], [10, 14]]; // front and back zones
  const shutterX = [2, 5, 8, 11, 14, 16];  // column positions

  // First storey windows (y: 1-2)
  for (let x of shutterX) {
    if (x < houseX[1] - 1) {
      g.set([x, 2, 1], "oak_trapdoor[open=false]");
      g.set([x, 2, houseZ[1] - 2], "dark_oak_trapdoor[open=false]");
    }
  }

  // Second storey windows (y: 7-8)
  for (let x of shutterX) {
    if (x < houseX[1] - 1) {
      g.set([x, 8, 1], "oak_trapdoor[open=false]");
      g.set([x, 8, houseZ[1] - 2], "dark_oak_trapdoor[open=false]");
    }
  }
}

// Chimney: x: 6-7, z: 4-5, y: 5-14
function chimney() {
  const chimX = [6, 8], chimZ = [4, 6], chimY = [5, 14];
  for (let x = chimX[0]; x < chimX[1]; x++) {
    for (let z = chimZ[0]; z < chimZ[1]; z++) {
      for (let y = chimY[0]; y < chimY[1]; y++) {
        g.set([x, y, z], P.chimney);
      }
    }
  }
}

// Porch/lean-to: x: 14-19, z: 10-14, y: 0-3
function porch() {
  const porchX = [14, 19], porchZ = [10, 14], porchY = [0, 3];

  // Support posts
  for (let x = porchX[0]; x < porchX[1]; x += 4) {
    for (let z = porchZ[0]; z < porchZ[1]; z += 3) {
      for (let y = porchY[0]; y < porchY[1]; y++) {
        g.set([x, y, z], P.porch + "_log[axis=y]");
      }
    }
  }

  // Roof: oak slabs sloped
  for (let x = porchX[0]; x < porchX[1]; x++) {
    for (let z = porchZ[0]; z < porchZ[1]; z++) {
      g.set([x, 3, z], P.porch + "_slab[type=top]");
    }
  }
}

// Potager garden wall and beds: x: 20-40, z: 2-28
function potager() {
  // Boundary fence
  for (let x = 20; x < 40; x++) {
    g.set([x, 1, 2], P.fence);
    g.set([x, 1, 28], P.fence);
  }
  for (let z = 2; z < 28; z++) {
    g.set([20, 1, z], P.fence);
    g.set([40, 1, z], P.fence);
  }

  // Main path (north-south): gravel at x: 30
  for (let z = 2; z < 28; z++) {
    g.set([30, 0, z], P.path);
  }

  // Cross path (east-west): at z: 14
  for (let x = 20; x < 40; x++) {
    g.set([x, 0, 14], P.path);
  }

  // Raised beds (dark oak fence borders)
  const bedGrid = [[23, 26], [27, 30], [32, 35]]; // x ranges
  const bedZRanges = [[5, 8], [10, 13], [18, 21], [24, 27]]; // z ranges

  for (let xR of bedGrid) {
    for (let zR of bedZRanges) {
      // Borders at y: 0 (on ground)
      for (let x = xR[0]; x <= xR[1]; x++) {
        g.set([x, 0, zR[0]], "dark_oak_fence");
        g.set([x, 0, zR[1]], "dark_oak_fence");
      }
      for (let z = zR[0]; z <= zR[1]; z++) {
        g.set([xR[0], 0, z], "dark_oak_fence");
        g.set([xR[1], 0, z], "dark_oak_fence");
      }
      // Fill with dirt/crops
      for (let x = xR[0] + 1; x < xR[1]; x++) {
        for (let z = zR[0] + 1; z < zR[1]; z++) {
          g.set([x, 0, z], "farmland");
        }
      }
    }
  }

  // Well/centre feature at x: 30, z: 14
  g.set([30, 0, 14], "crafting_table");

  // Fruit trees (x: 35-37, z: 4-8)
  for (let z = 4; z < 9; z++) {
    g.set([36, 0, z], "oak_log[axis=y]");
    g.set([36, 1, z], "oak_log[axis=y]");
    g.set([36, 2, z], "oak_leaves[persistent=true]");
    g.set([37, 2, z], "oak_leaves[persistent=true]");
  }
}

// Tool shed: x: 28-31, z: 22-25, y: 0-3
function shed() {
  const shedX = [28, 32], shedZ = [22, 26], shedY = [0, 3];
  shell(g, { x: shedX, z: shedZ, y: shedY }, P.porch);

  // Door
  g.set([28, 1, 23], "oak_door[facing=west,half=lower]");

  // Roof
  for (let x = shedX[0]; x < shedX[1]; x++) {
    for (let z = shedZ[0]; z < shedZ[1]; z++) {
      g.set([x, 3, z], P.roof + "_slab[type=top]");
    }
  }
}

// Gate arch: x: 30, z: 10
function arch() {
  g.set([29, 0, 10], "oak_fence_gate[facing=south]");
  g.set([30, 0, 10], "oak_fence_gate[facing=south]");
  g.set([31, 0, 10], "oak_fence_gate[facing=south]");
  g.set([30, 1, 10], "oak_trapdoor[facing=north,open=true]");
  g.set([30, 2, 10], "oak_trapdoor[facing=north,open=true]");
}

// Lanterns at corners and gate
function lanterns() {
  const corners = [[20, 2], [40, 2], [20, 28], [40, 28]];
  for (let [x, z] of corners) {
    g.set([x, 2, z], "lantern[hanging=false]");
  }
  g.set([29, 1, 10], "lantern[hanging=false]");
}

house();
chimney();
porch();
potager();
shed();
arch();
lanterns();

g.save("/Volumes/ext1/swe/repos/mc-design-eval/benchmarks/plugin-baseline/runs/build-1/farmhouse-lean/build.nbt");
console.log(JSON.stringify({ saved: "build.nbt" }));

