import { Grid } from "../../../../../../minecraft-design/tools/src/build.mjs";

const g = new Grid([40, 14, 36]);
const [W, H, D] = g.size;

const P = {
  wall: "stone_bricks",
  trim: "chiseled_stone_bricks",
  roof: "dark_oak",
  chimney: "red_bricks",
  porch: "oak",
  path: "gravel",
  fence: "stone_brick_fence",
};

function house() {
  const [x0, x1] = [0, 18], [z0, z1] = [0, 14], [y0, y1] = [0, 10];

  // Outer walls
  for (let x = x0; x < x1; x++) {
    for (let z = z0; z < z1; z++) {
      for (let y = y0; y < y1; y++) {
        const isWall = x === x0 || x === x1 - 1 || z === z0 || z === z1 - 1;
        if (isWall) g.set([x, y, z], P.wall);
      }
    }
  }

  // Mid-floor at y: 5
  for (let x = x0; x < x1; x++) {
    for (let z = z0; z < z1; z++) {
      g.set([x, 5, z], P.trim);
    }
  }

  // Windows: trapdoors at y: 2 (first floor) and y: 8 (second)
  const wX = [2, 5, 8, 11, 14, 16];
  for (let x of wX) {
    g.set([x, 2, 1], "oak_trapdoor[open=false]");
    g.set([x, 2, 12], "dark_oak_trapdoor[open=false]");
    g.set([x, 8, 1], "oak_trapdoor[open=false]");
    g.set([x, 8, 12], "dark_oak_trapdoor[open=false]");
  }
}

function chimney() {
  const [x0, x1] = [6, 8], [z0, z1] = [4, 6];
  for (let x = x0; x < x1; x++) {
    for (let z = z0; z < z1; z++) {
      for (let y = 5; y < 14; y++) {
        g.set([x, y, z], P.chimney);
      }
    }
  }
}

function porch() {
  const [x0, x1] = [14, 19], [z0, z1] = [10, 14];

  // Posts at corners
  g.set([x0, 0, z0], P.porch + "_log[axis=y]");
  g.set([x0, 1, z0], P.porch + "_log[axis=y]");
  g.set([x0, 2, z0], P.porch + "_log[axis=y]");

  g.set([x1 - 1, 0, z0], P.porch + "_log[axis=y]");
  g.set([x1 - 1, 1, z0], P.porch + "_log[axis=y]");
  g.set([x1 - 1, 2, z0], P.porch + "_log[axis=y]");

  // Slabs for roof
  for (let x = x0; x < x1; x++) {
    for (let z = z0; z < z1; z++) {
      g.set([x, 3, z], P.porch + "_slab[type=top]");
    }
  }
}

function potager() {
  // Boundary fence (stone brick)
  for (let x = 20; x <= 40; x++) {
    g.set([x, 1, 2], P.fence);
    g.set([x, 1, 28], P.fence);
  }
  for (let z = 2; z <= 28; z++) {
    g.set([20, 1, z], P.fence);
    g.set([40, 1, z], P.fence);
  }

  // Main paths: gravel
  for (let z = 2; z < 28; z++) {
    g.set([30, 0, z], P.path);
  }
  for (let x = 20; x <= 40; x++) {
    g.set([x, 0, 14], P.path);
  }

  // Raised beds with dark oak fence borders
  const beds = [
    [[23, 26], [5, 8]],
    [[23, 26], [10, 13]],
    [[23, 26], [18, 21]],
    [[23, 26], [24, 27]],
    [[32, 35], [5, 8]],
    [[32, 35], [10, 13]],
    [[32, 35], [18, 21]],
    [[32, 35], [24, 27]],
  ];

  for (let [[x0, x1], [z0, z1]] of beds) {
    for (let x = x0; x <= x1; x++) {
      g.set([x, 0, z0], "dark_oak_fence");
      g.set([x, 0, z1], "dark_oak_fence");
    }
    for (let z = z0; z <= z1; z++) {
      g.set([x0, 0, z], "dark_oak_fence");
      g.set([x1, 0, z], "dark_oak_fence");
    }
    for (let x = x0 + 1; x < x1; x++) {
      for (let z = z0 + 1; z < z1; z++) {
        g.set([x, 0, z], "farmland");
      }
    }
  }

  // Well/centre feature
  g.set([30, 0, 14], "crafting_table");

  // Fruit trees
  for (let z = 4; z < 9; z++) {
    g.set([36, 0, z], "oak_log[axis=y]");
    g.set([36, 1, z], "oak_log[axis=y]");
    g.set([36, 2, z], "oak_leaves[persistent=true]");
    g.set([37, 2, z], "oak_leaves[persistent=true]");
  }
}

function shed() {
  const [x0, x1] = [28, 32], [z0, z1] = [22, 26];

  // Walls
  for (let x = x0; x < x1; x++) {
    for (let z = z0; z < z1; z++) {
      for (let y = 0; y < 3; y++) {
        const isWall = x === x0 || x === x1 - 1 || z === z0 || z === z1 - 1;
        if (isWall) g.set([x, y, z], P.porch);
      }
    }
  }

  // Door
  g.set([x0, 1, 23], "oak_door[facing=west,half=lower]");

  // Roof
  for (let x = x0; x < x1; x++) {
    for (let z = z0; z < z1; z++) {
      g.set([x, 3, z], P.roof + "_slab[type=top]");
    }
  }
}

function arch() {
  g.set([29, 0, 10], "oak_fence_gate[facing=south]");
  g.set([30, 0, 10], "oak_fence_gate[facing=south]");
  g.set([31, 0, 10], "oak_fence_gate[facing=south]");
  g.set([30, 1, 10], "oak_trapdoor[open=true]");
  g.set([30, 2, 10], "oak_trapdoor[open=true]");
}

function lanterns() {
  g.set([20, 2, 2], "lantern[hanging=false]");
  g.set([40, 2, 2], "lantern[hanging=false]");
  g.set([20, 2, 28], "lantern[hanging=false]");
  g.set([40, 2, 28], "lantern[hanging=false]");
  g.set([29, 1, 10], "lantern[hanging=false]");
}

house();
chimney();
porch();
potager();
shed();
arch();
lanterns();

g.save("/Volumes/ext1/swe/repos/mc-design-eval/benchmarks/plugin-baseline/runs/build-1/farmhouse-lean/build.nbt");
