  const [x0, x1] = [1, 18], [z0, z1] = [1, 14], [y0, y1] = [1, 10];

  for (let x = x0; x < x1; x++) {
    for (let z = z0; z < z1; z++) {
      for (let y = y0; y < y1; y++) {
        const isWall = x === x0 || x === x1 - 1 || z === z0 || z === z1 - 1;
        if (isWall) g.set(x, y, z, "stone_bricks");
      }
    }
  }

  for (let x = x0; x < x1; x++) {
    for (let z = z0; z < z1; z++) {
      g.set(x, 5, z, "chiseled_stone_bricks");
    }
  }

  const wX = [3, 6, 9, 12, 15];
  for (let x of wX) {
    g.set(x, 2, z0, "air");
    g.set(x, 2, z1 - 1, "air");
    g.set(x, 8, z0, "air");
    g.set(x, 8, z1 - 1, "air");
  }
}

