  for (let x = x0; x < x1; x++) {
    for (let z = z0; z < z1; z++) {
      for (let y = y0; y < y1; y++) {
        const isWall = x === x0 || x === x1 - 1 || z === z0 || z === z1 - 1;
        if (isWall) g.set(x, y, z, "stone_bricks");
      }
    }
  }

  for (let x = x0; x < x1; x++) {
    for (let z = z0; z < z1; z++) {
      g.set(x, 5, z, "chiseled_stone_bricks");
    }
  }

  const wX = [3, 6, 9, 12, 15];
  for (let x of wX) {
    g.set(x, 2, z0, "air");
    g.set(x, 2, z1 - 1, "air");
    g.set(x, 8, z0, "air");
    g.set(x, 8, z1 - 1, "air");
  }
}

function chimney() {
  const [x0, x1] = [7, 9], [z0, z1] = [5, 7];
  for (let x = x0; x < x1; x++) {
    for (let z = z0; z < z1; z++) {
      for (let y = 5; y < 13; y++) {
        g.set(x, y, z, "bricks");
      }
    }
  }
}

function porch() {
  const [x0, x1] = [15, 19], [z0, z1] = [11, 14];
  for (let x = x0; x < x1; x++) {
    for (let z = z0; z < z1; z++) {
      g.set(x, 1, z, "oak_log");
      g.set(x, 2, z, "oak_log");
      g.set(x, 3, z, "oak_slab");
    }
  }
}

