  for (let x = 21; x <= 39; x++) {
    g.set(x, 1, 3, "stone_brick_wall");
    g.set(x, 1, 27, "stone_brick_wall");
  }
  for (let z = 3; z <= 27; z++) {
    g.set(21, 1, z, "stone_brick_wall");
    g.set(39, 1, z, "stone_brick_wall");
  }

  for (let z = 3; z < 27; z++) {
    g.set(30, 1, z, "gravel");
  }
  for (let x = 21; x <= 39; x++) {
    g.set(x, 1, 15, "gravel");
  }

  const beds = [
    [[24, 27], [6, 9]],
    [[24, 27], [11, 14]],
    [[24, 27], [19, 22]],
    [[24, 27], [24, 27]],
    [[33, 36], [6, 9]],
    [[33, 36], [11, 14]],
    [[33, 36], [19, 22]],
    [[33, 36], [24, 27]],
  ];

  for (let [[x0, x1], [z0, z1]] of beds) {
    for (let x = x0; x <= x1; x++) {
      g.set(x, 1, z0, "dark_oak_fence");
      g.set(x, 1, z1, "dark_oak_fence");
