  const [x0, x1] = [29, 33], [z0, z1] = [23, 27];

  for (let x = x0; x < x1; x++) {
    for (let z = z0; z < z1; z++) {
      g.set(x, 1, z, "oak_log");
      g.set(x, 2, z, "oak_log");
      g.set(x, 3, z, "oak_slab");
    }
